class Solution {
public:
    int longestEqualSubarray(vector<int>& nums, int k) {
        unordered_map<int, vector<int>> pos;
        for (int i = 0; i < (int)nums.size(); i++) pos[nums[i]].push_back(i);
        int ans = 1;
        for (auto& [v, lst] : pos) {
            int l = 0;
            for (int r = 0; r < (int)lst.size(); r++) {
                while (lst[r] - lst[l] - (r - l + 1) > k) l++;
                ans = max(ans, r - l + 1);
            }
        }
        return ans;
    }
};

