class Solution {
    public int longestEqualSubarray(int[] nums, int k) {
        Map<Integer, List<Integer>> pos = new HashMap<>();
        for (int i = 0; i < nums.length; i++)
            pos.computeIfAbsent(nums[i], x -> new ArrayList<>()).add(i);
        int ans = 1;
        for (List<Integer> lst : pos.values()) {
            int l = 0;
            for (int r = 0; r < lst.size(); r++) {
                while (lst.get(r) - lst.get(l) - (r - l + 1) > k) l++;
                ans = Math.max(ans, r - l + 1);
            }
        }
        return ans;
    }
}

