from collections import Counter
class Solution:
    def longestEqualSubarray(self, nums: List[int], k: int) -> int:
        cnt = Counter()
        l = 0
        best = 0
        for r, v in enumerate(nums):
            cnt[v] += 1
            while (r - l + 1) - max(cnt.values()) > k:
                cnt[nums[l]] -= 1
                l += 1
            best = max(best, max(cnt.values()))
        return best

