class Solution {
public:
    int longestEqualSubarray(vector<int>& nums, int k) {
        unordered_map<int,int> cnt;
        int l = 0, best = 0, mx = 0;
        for (int r = 0; r < (int)nums.size(); r++) {
            mx = max(mx, ++cnt[nums[r]]);
            while ((r - l + 1) - mx > k) {
                if (--cnt[nums[l]] == mx - 1) {
                    mx = 0;
                    for (auto& [v, c] : cnt) mx = max(mx, c);
                }
                l++;
            }
            best = max(best, mx);
        }
        return best;
    }
};

