class Solution {
    public int longestEqualSubarray(int[] nums, int k) {
        Map<Integer, Integer> cnt = new HashMap<>();
        int l = 0, best = 0, mx = 0;
        for (int r = 0; r < nums.length; r++) {
            mx = Math.max(mx, cnt.merge(nums[r], 1, Integer::sum));
            while ((r - l + 1) - mx > k) {
                int c = cnt.merge(nums[l], -1, Integer::sum);
                if (c == mx - 1) {
                    mx = 0;
                    for (int v : cnt.values()) mx = Math.max(mx, v);
                }
                l++;
            }
            best = Math.max(best, mx);
        }
        return best;
    }
}

